func sweepQuarantineDebris(chainDir string) {
	parent := filepath.Dir(chainDir)
	base := filepath.Base(chainDir)
	entries, err := os.ReadDir(parent)
	if err != nil {
		return
	}
	var stages, trashes []string
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		name := e.Name()
		if isMergeTempName(name, base, quarantineStagePrefix) {
			stages = append(stages, name)
		}
		if isMergeTempName(name, base, quarantineTrashPrefix) {
			trashes = append(trashes, name)
		}
	}

	_, statErr := os.Stat(chainDir)
	chainMissing := errors.Is(statErr, os.ErrNotExist)

	if chainMissing {
		// Prefer completing the swap from a fully validated staged chain; the
		// parked old chain stays as the quarantine.
		completed := false
		for _, name := range stages {
			sp := filepath.Join(parent, name)
			if _, verr := validateBackupChain(sp); verr != nil {
				continue
			}
			if rerr := os.Rename(sp, chainDir); rerr == nil {
				completed = true
				_ = syncDirectory(parent)
				break
			}
		}
		if !completed && len(trashes) > 0 {
			// No usable replacement: roll the whole parked old chain back.
			if err := os.Rename(filepath.Join(parent, trashes[0]), chainDir); err == nil {
				_ = syncDirectory(parent)
				trashes = trashes[1:]
			}
		}
	}

	changed := false
	for _, name := range stages {
		// A stage that completed the swap now lives at chainDir; any remaining
		// stage is pre-commit debris or an invalid rollback candidate.
		if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
			changed = true
		}
	}
	// When the chain is present, surviving trash directories are retained
	// quarantines. Only when the chain is still missing do we clear them, so
	// no sibling ever shadows the path a rollback or completion needs.
	if chainMissing {
		for _, name := range trashes {
			if err := os.RemoveAll(filepath.Join(parent, name)); err == nil {
				changed = true
			}
		}
	}
	if changed {
		_ = syncDirectory(parent)
	}
}

