		t.Fatalf("get a: got=%q ok=%v err=%v", got, ok, err)
	}
	if err := s.Put("a", []byte("two")); err != nil {
		t.Fatal(err)
	}
	if got, ok, _ := s.Get("a"); !ok || string(got) != "two" {
