func TestVerifyChainConcurrentActivity(t *testing.T) {
	s := openStore(t, tempDir(t))
	chain := filepath.Join(t.TempDir(), "chain")
	for i := 0; i < 20; i++ {
		if err := s.Put(fmt.Sprintf("seed-%02d", i), []byte("v")); err != nil {
			t.Fatal(err)
		}
	}
	if err := s.Backup(chain); err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 3; i++ {
		if err := s.Put(fmt.Sprintf("ring-%d", i), []byte("v")); err != nil {
			t.Fatal(err)
		}
		if err := s.BackupIncremental(chain); err != nil {
			t.Fatal(err)
		}
	}

	var wg sync.WaitGroup
	stop := make(chan struct{})
	var writes, reads int64
	var mu sync.Mutex
	wg.Add(2)
	go func() { // writer
		defer wg.Done()
		for i := 0; ; i++ {
			select {
			case <-stop:
				return
			default:
			}
			if err := s.CommitBatch([]BatchOp{{Key: fmt.Sprintf("live-%04d", i), Value: []byte("x")}}); err != nil {
				return
			}
			mu.Lock()
			writes++
			mu.Unlock()
		}
	}()
	go func() { // lock-free reader
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
			}
			if _, ok, err := s.Get("seed-000"); err != nil || !ok {
				t.Errorf("read during verify failed: ok=%v err=%v", ok, err)
				return
			}
			mu.Lock()
			reads++
			mu.Unlock()
		}
	}()

	// Verify repeatedly; it must neither block the foreground nor mutate the
	// backed-up store.
	for i := 0; i < 3; i++ {
		if err := s.VerifyChain(chain); err != nil {
			t.Fatalf("verify %d: %v", i, err)
		}
	}
	time.Sleep(20 * time.Millisecond)
	close(stop)
	wg.Wait()
	mu.Lock()
	defer mu.Unlock()
	if writes == 0 || reads == 0 {
		t.Fatalf("foreground stalled during verify: writes=%d reads=%d", writes, reads)
	}
}

func TestIncrementalForgottenDeleteZeroAdvanceRing(t *testing.T) {
	// A chain whose tip watermark is one past its terminal frame count: the
	// store restored from it extends the chain from a watermark equal to the
	// next commit sequence once one delete is compacted into oblivion.
	src := openStore(t, tempDir(t))
	if err := src.Put("k", []byte("v1")); err != nil {
		t.Fatal(err)
	}
	if err := src.Put("k", []byte("v2")); err != nil {
		t.Fatal(err) // overwritten history; head watermark 2, one terminal frame
	}
	if err := src.Put("keep", []byte("kept")); err != nil {
		t.Fatal(err)
	}
	chain := filepath.Join(t.TempDir(), "chain")
	if err := src.Backup(chain); err != nil {
		t.Fatal(err)
	}
	src.Close()

	target := filepath.Join(t.TempDir(), "restored")
	rs, err := Restore(chain, target)
	if err != nil {
		t.Fatal(err)
	}
	// Delete the key and compact hard so its tombstone is forgotten while the
	// anchor stays at the head watermark: a flat, tombstone-only ring.
	if err := rs.Delete("k"); err != nil {
		t.Fatal(err)
	}
	if err := rs.Compact(); err != nil {
		t.Fatal(err)
	}
	if err := rs.Compact(); err != nil {
		t.Fatal(err)
	}
	if _, ok, _ := rs.Get("k"); ok {
		t.Fatal("setup: deleted key still visible")
	}
	if err := rs.BackupIncremental(chain); err != nil {
		t.Fatalf("zero-advance forgotten-delete ring rejected: %v", err)
	}

	// The flat ring passes whole-chain validation and online verification.
	art, err := validateBackupChain(chain)
	if err != nil {
		t.Fatalf("flat ring chain invalid: %v", err)
	}
	if art.ringCount != 1 || art.endWM != art.head.watermark {
		t.Fatalf("unexpected chain tip: rings=%d endWM=%d headWM=%d",
			art.ringCount, art.endWM, art.head.watermark)
	}
	if err := rs.VerifyChain(chain); err != nil {
		t.Fatalf("verify flat ring: %v", err)
	}

	// Synthesized to the tip watermark the old value stays unreadable: the
	// delete does not resurrect.
	t2 := filepath.Join(t.TempDir(), "again")
	r2, err := Restore(chain, t2)
	if err != nil {
		t.Fatalf("restore flat-ring chain: %v", err)
	}
	defer r2.Close()
	if _, ok, _ := r2.Get("k"); ok {
		t.Fatal("forgotten delete resurrected through zero-advance ring")
	}
	if v, ok, _ := r2.Get("keep"); !ok || string(v) != "kept" {
		t.Fatalf("unrelated live key lost: %q ok=%v", v, ok)
	}

	// A normal ring appended afterwards continues from the flat tip.
	if err := rs.Put("new", []byte("n")); err != nil {
		t.Fatal(err)
	}
	if err := rs.BackupIncremental(chain); err != nil {
		t.Fatalf("incremental after flat ring: %v", err)
	}
	t3 := filepath.Join(t.TempDir(), "later")
	r3, err := Restore(chain, t3)
	if err != nil {
		t.Fatalf("restore extended chain: %v", err)
	}
	defer r3.Close()
	if v, ok, _ := r3.Get("new"); !ok || string(v) != "n" {
		t.Fatalf("post-flat append missing: %q ok=%v", v, ok)
	}
	if _, ok, _ := r3.Get("k"); ok {
		t.Fatal("deleted key back after further append")
	}
}

